import{_ as s,o as t,a as l,b as n}from"./app.DKoEZOcr.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"特殊寄存器访问","link":"/api/SIMD-API/c_api/spr/spr"},{"text":"asc_set_ctrl","link":"/api/SIMD-API/c_api/spr/asc_set_ctrl"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/spr/asc_set_ctrl.md","filePath":"api/SIMD-API/c_api/spr/asc_set_ctrl.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788180402000}'),e={name:"api/SIMD-API/c_api/spr/asc_set_ctrl.md"};function p(i,a,c,r,d,h){return t(),l("div",null,[...a[0]||(a[0]=[n(`<div><article class="markdown-body"><h1>asc_set_ctrl</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>对CTRL寄存器（控制寄存器）的特定比特位进行设置。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_set_ctrl</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">config</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">config</td><td align="left">输入</td><td align="left">待设置的寄存器值。常用CTRL寄存器比特位说明参考表2。</td></tr></tbody></table><p><strong>表2</strong> 常用CTRL寄存器比特位说明</p><table><thead><tr><th align="left">CTRL比特位</th><th align="left">功能</th></tr></thead><tbody><tr><td align="left">CTRL[48]</td><td align="left">用于控制浮点计算/部分浮点精度转换的饱和模式。<br>- 1&#39;b0：饱和模式，INF输出会被饱和为±MAX，NAN输出会被饱和为0；<br> - 1&#39;b1：非饱和模式，INF/NAN保持原输出。<br> 该控制位仅支持如下数据类型：<br>- 浮点数计算时支持half数据类型；<br>- 浮点数精度转换时支持如下数据类型：hifloat8_t、fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t、half、bfloat16_t。</td></tr><tr><td align="left">CTRL[49]</td><td align="left">用于控制标量单元访问Unified Buffer（UB）时是否经过DCache。DCache的读取速度快于UB，因此在对UB进行大量读取，且UB中数据不被Vector单元写入时，可选择开启该模式。<br>- 1&#39;b0：标量单元访问UB时，直接从UB中读取；<br> - 1&#39;b1：标量单元访问UB时，从DCache中读取。</td></tr><tr><td align="left">CTRL[50]</td><td align="left">用于控制fp8_e8m0_t、fp8_e5m2_t、fp8_e4m3fn_t相关场景的饱和模式。<br>- 1&#39;b0：饱和模式；<br> - 1&#39;b1：非饱和模式。</td></tr><tr><td align="left">CTRL[53]</td><td align="left">用于控制整数计算指令的饱和模式。<br>- 1&#39;b0：截断模式，溢出值按目标数据类型位数截断，保留低位，舍弃高位；<br>- 1&#39;b1：饱和模式，溢出值饱和到±MAX。</td></tr><tr><td align="left">CTRL[56]</td><td align="left">MASK模式控制位。MASK用于辅助SIMD指令执行，由于CTRL[56]指示两种模式：<br>- 1&#39;b0：向量操作中的掩码寄存器。每位对应向量中一个元素，标记该元素是否参与计算。&#39;1&#39;表示对应元素将被计算；&#39;0&#39;表示对应元素将不被计算；<br>- 1&#39;b1：MASK[31:0]用于指示SIMD指令实际操作的元素数量。实际重复次数由VECTOR自动推断，此时参数repeat time(Xt[63:56])被忽略。</td></tr><tr><td align="left">CTRL[59]</td><td align="left">用于控制浮点数转整数或整数转整数时的精度转换饱和模式，仅在CTRL[60]开启时生效。<br>- 1&#39;b0：饱和模式，溢出值饱和到±MAX；<br>- 1&#39;b1：截断模式：溢出值按照目标数据类型位数截断，保留低位，舍弃高位。</td></tr><tr><td align="left">CTRL[60]</td><td align="left">饱和控制策略选择位。<br>- 1&#39;b0：按单指令/API路径配置饱和（对应<code>asc_override_strategy::USE_API</code>）；<br>- 1&#39;b1：使用全局CTRL饱和配置（对应<code>asc_override_strategy::USE_GLOBAL</code>），此时CTRL[59]的CAST配置才会生效。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>使用前需要先用<a href="asc_get_ctrl.html">asc_get_ctrl()</a>获取当前值，仅对需要变更的bit位进行修改。</li><li>常用可配置比特位包括CTRL[48]、CTRL[50]、CTRL[53]、CTRL[56]、CTRL[59]、CTRL[60]。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 将CTRL[48]设置为非饱和模式</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">ori_config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc_get_ctrl</span><span class="p">();</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">(</span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">1</span><span class="p">)</span><span class="w"> </span><span class="o">&lt;&lt;</span><span class="w"> </span><span class="mi">48</span><span class="p">);</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">config</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">ori_config</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="n">mask</span><span class="p">;</span>
<span class="n">asc_set_ctrl</span><span class="p">(</span><span class="n">config</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const f=s(e,[["render",p]]);export{o as __pageData,f as default};
